        arrakisBalance0 = 0;
        arrakisBalance1 = 0;

        if (amount0 > 0) {
            token0.safeTransfer(arrakisTreasury, amount0);
        }

        if (amount1 > 0) {
            token1.safeTransfer(arrakisTreasury, amount1);
        }
